{
  "_note": "Tidepool as a project that has only Figma: no code yet, in build mode. Used by the build evaluation (test/skill-evals). Every name is invented.",
  "figmaFileKey": "b0LpOCBsaRgo8lUqbkQNaY",
  "build": true,
  "maxSnapshotAgeDays": 30,
  "figma": {
    "modes": [
      {
        "name": "Light",
        "snapshotKey": "light",
        "cssSelector": "root"
      },
      {
        "name": "Dark",
        "snapshotKey": "dark",
        "cssSelector": "data:theme=dark"
      }
    ]
  },
  "paths": {
    "themeCSS": [
      "src/styles/tokens.css",
      "src/components/button.css",
      "src/components/chip.css",
      "src/components/disclosure.css",
      "src/components/field.css",
      "src/components/stepper.css",
      "src/components/tag.css"
