    {
      "id": "title",
      "component": "Text",
      "props": {
        "text": "Notification Settings",
        "as": "h1",
        "style": "m"
      }
    },
    {
      "id": "emailSection",
      "component": "Stack",
      "props": {
        "gap": "padding/s"
      },
      "children": [
        {
          "component": "Text",
          "props": {
            "text": "Email Notifications",
            "as": "h3",
            "style": "m"
          }
        },
        {
          "id": "emailSwitch",
          "component": "chip",
          "props": {
            "Label": "Enable email notifications",
            "Size": "M",
            "Icon": false,
            "standInFor": "switch"
          }
        }
      ]
    },
    {
      "id": "pushSection",
      "component": "Stack",
      "props": {
        "gap": "padding/s"
      },
      "children": [
        {
          "component": "Text",
          "props": {
            "text": "Push Notifications",
            "as": "h3",
            "style": "m"
          }
        },
        {
          "id": "pushSwitch",
          "component": "chip",
          "props": {
            "Label": "Enable push notifications",
            "Size": "M",
            "Icon": false,
            "standInFor": "switch"
          }
        }
      ]
    },
    {
      "id": "confirmation",
      "component": "tag",
      "props": {
        "Tone": "Positive",
        "Label": "Settings saved successfully"
      }
    },
