    "empty": {
      "emailSection": null,
      "pushSection": null,
      "saveButton": null,
      "confirmation": null,
      "title": {
        "component": "Text",
        "props": {
          "text": "Notifications unavailable",
          "as": "h1",
          "style": "m"
        }
      }
    }
  }
}

